-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 23: Dados temporais — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('fb5d4de9-d85f-5d2e-ac3c-bc391f379e14', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Um banco temporal registra, além dos fatos:', '["A referência temporal de sua validade ou ocorrência conforme o modelo.","Somente valores agregados.","Exclusivamente datas de backups.","Somente o horário de login do DBA.","Apenas o tempo de execução do SELECT."]'::jsonb, 0, 'O capítulo trata de fatos associados a pontos e períodos temporais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.1, páginas 1159–1164 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('910f29a3-6253-5087-a443-7e7497d8a4ec', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Guardar apenas o departamento atual de um empregado impede responder diretamente:', '["Quantos empregados atuais estão cadastrados.","Se o registro atual existe.","Qual é seu departamento atual.","Qual identificador ele possui.","Em quais departamentos ele trabalhou no passado."]'::jsonb, 4, 'Estado atual e histórico são conteúdos informacionais diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.1, páginas 1159–1164 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('59617176-3cfe-5550-b207-8902e829eb33', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Acrescentar colunas de início e fim a tabelas resolve toda complexidade temporal?', '["Sim, elimina sobreposições automaticamente.","Sim, garante consistência de todos os períodos.","Não, porque datas não podem ser atributos.","Não; consultas e restrições ainda podem tornar-se complexas.","Sim, dispensa qualquer validação."]'::jsonb, 3, 'O capítulo usa essa dificuldade para motivar suporte explícito a intervalos e operadores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.2, páginas 1165–1173 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('09fbc6a2-6e03-5146-94d3-3495fd6c81c2', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Tratar [d04:d10] como um único valor permite:', '["Definir operadores e restrições próprios de intervalos.","Dispensar tipos.","Eliminar a ordem temporal.","Transformar todo período em texto sem semântica.","Ignorar seus limites."]'::jsonb, 0, 'O intervalo é um valor de tipo apropriado, não apenas dois campos sem operações comuns.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6d50f705-f577-5055-a7fc-b47f5074c419', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Qual requisito básico deve ser definido para o tipo de ponto considerado no capítulo?', '["Um índice físico obrigatório.","Uma ordenação total dos valores.","Uma chave estrangeira em cada valor.","Uma operação de commit por data.","Um nome de usuário por ponto."]'::jsonb, 1, 'Comparar pontos é fundamental para definir início, fim e relações entre intervalos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ce09b2f3-bf28-58f5-914d-6c9a990750cf', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Um intervalo fechado com início maior que o fim deve ser:', '["Confirmado sem restrições.","Aceito como intervalo de duração negativa.","Rejeitado como intervalo inválido nessa convenção.","Tratado como uma chave candidata.","Convertido em NULL automaticamente."]'::jsonb, 2, 'A validade dos limites integra a definição do tipo de intervalo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('df1ee074-2dfb-5ebd-9fb7-8c7f8254ddf4', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Nos intervalos fechados de dias inteiros, [2:5] INTERSECT [4:8] é:', '["[2:3].","[2:8].","[4:5].","[1:8].","[6:8]."]'::jsonb, 2, 'A interseção contém os pontos presentes em ambos os intervalos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b3db1102-e0fd-5b40-a3ee-9faa02d69bb8', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Nos intervalos fechados de dias inteiros, [2:5] e [6:8] são:', '["Iguais.","Adjacentes, sem ponto em comum.","Necessariamente inválidos.","Um contido no outro.","Sobrepostos nos pontos 5 e 6."]'::jsonb, 1, 'Com granularidade diária, o ponto seguinte a 5 é 6; a convenção dos limites importa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f113a777-6df9-5e68-ae52-90f107c71830', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Nos intervalos fechados de dias inteiros, unir [2:5] e [4:8] como período contínuo resulta em:', '["[2:8].","[4:5].","[6:8].","[4:8] apenas.","[2:3]."]'::jsonb, 0, 'Os intervalos se sobrepõem e sua união forma um único intervalo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b5a6c38a-57b7-5550-a911-310507bb04c8', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Fácil', 'O intervalo fechado [3:3], na convenção apresentada, representa:', '["Um intervalo vazio obrigatoriamente.","Um período infinito.","Uma variável sem valor.","Um intervalo inválido.","Um intervalo unitário com um ponto."]'::jsonb, 4, 'Limites iguais podem representar um único ponto do tipo considerado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('39e288b2-75e3-57d5-9017-21567c12f7fe', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'O operador EXPAND transforma intervalos de uma relação unária em:', '["Somente seus pontos finais.","Cópias de todas as tabelas.","Intervalos unitários para os pontos cobertos.","Linhas sem qualquer tipo.","Uma contagem sem relação de resultado."]'::jsonb, 2, 'A forma expandida explicita a cobertura ponto a ponto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a87eec5-bfc5-5404-95be-f227dcac085c', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'COLLAPSE procura representar a mesma cobertura temporal usando:', '["Números sem ordenação.","Uma linha para cada usuário.","Somente o primeiro ponto.","A exclusão de todos os intervalos sobrepostos.","Intervalos máximos resultantes da consolidação apropriada."]'::jsonb, 4, 'A consolidação preserva os pontos cobertos e reduz representações redundantes ou fragmentadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7ac20306-34b8-54c5-b704-2fa4363afdd1', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'PACK e UNPACK generalizam o tratamento de intervalos para:', '["Apenas logs de recuperação.","Dados sem qualquer tempo.","Tipos sem comparação.","Somente tabelas sem atributos.","Relações que podem conter outros atributos além do intervalo."]'::jsonb, 4, 'O processamento considera os demais atributos ao agrupar ou expandir a informação temporal.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9ed07f89-4c4a-5c48-80b2-212b1f19a8eb', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Consolidar períodos adjacentes do mesmo empregado e mesmo cargo pode:', '["Eliminar a necessidade de identificar o empregado.","Criar um novo ponto sem data.","Mudar o cargo para todos os empregados.","Preservar a informação temporal com uma representação menos fragmentada.","Apagar necessariamente o histórico."]'::jsonb, 3, 'A consolidação depende de os demais valores e a cobertura temporal serem compatíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a1c54fe3-02d0-5610-ad26-d1b0531cd8e1', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Difícil', 'Por que operadores temporais generalizados são úteis?', '["Dispensam a semântica das consultas.","Eliminam qualquer referência ao tempo.","Substituem autenticação.","Abreviam padrões de desempacotar, operar e reempacotar, com possibilidade de otimização.","Obrigam expansão física de todos os dias."]'::jsonb, 3, 'A semântica pode ser definida por expansão sem exigir uma implementação ingênua dessa expansão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.5, páginas 1197–1203 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d8569a93-4726-5384-9973-ba9f9cf31658', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Históricos de nome e endereço mudam em datas diferentes. Separá-los temporalmente pode evitar:', '["Toda junção de consultas.","A existência de identificadores.","Qualquer restrição temporal.","Repetição e fragmentação desnecessárias de fatos com ritmos distintos de mudança.","A necessidade de armazenar datas."]'::jsonb, 3, 'O projeto deve considerar quais atributos variam juntos e quais possuem históricos independentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.6, páginas 1204–1212 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d0ef74f-0d33-5f3d-8933-5d55eb7b5632', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Dois cargos exclusivos para o mesmo empregado em períodos sobrepostos podem representar:', '["Somente uma diferença de ordenação.","Contradição temporal, conforme a regra de exclusividade.","Uma DF trivial garantida.","Um backup duplicado.","Ausência de integridade referencial apenas."]'::jsonb, 1, 'A restrição precisa proibir estados simultâneos incompatíveis no período relevante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.7, páginas 1213–1220 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d876c86-17b0-55b2-84dd-a465d422b17f', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Uma chave (empregado, intervalo) impede sozinha toda sobreposição de períodos do empregado?', '["Não, porque chaves não existem em dados temporais.","Não; intervalos diferentes ainda podem compartilhar pontos.","Sim, desde que o empregado seja numérico.","Sim, pois intervalos distintos nunca se cruzam.","Sim, se houver duas colunas."]'::jsonb, 1, 'Unicidade da combinação não é uma restrição de não sobreposição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.7, páginas 1213–1220 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('51e6fa85-5b0d-52ac-b4a9-424130f5cde7', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Difícil', 'Uma referência temporal entre dependente e entidade exige atenção a:', '["Cobertura dos períodos em que a entidade referenciada precisa existir.","Somente quantidade de índices.","A ordem de criação das tabelas.","Apenas existência atual, em qualquer cenário.","Somente igualdade textual dos nomes."]'::jsonb, 0, 'Referência temporal pode exigir existência durante todo o intervalo relevante, não em um instante arbitrário.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.7, páginas 1213–1220 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4922856b-09e7-5f9d-ae60-c05b940fa78c', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Ao escrever uma questão sobre sobreposição de períodos, por que declarar limites e granularidade?', '["Para ocultar a semântica do intervalo.","Para eliminar todos os pontos finais.","Para evitar respostas diferentes decorrentes de convenções temporais distintas.","Para transformar datas em índices.","Para tornar dispensável a comparação."]'::jsonb, 2, 'Intervalos abertos, fechados e diferentes unidades de tempo podem alterar relações de adjacência e interseção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
